Section HCW.
  Context {HCEIL : HeapCeil}.

Lemma NoDup_of_ids : forall (LB : list block), List.NoDup (map blk_id LB) -> List.NoDup LB.
Proof.
  induction LB as [|b LB IH]; intros ND; [constructor|]. cbn in ND. inversion ND as [|x l NI ND']; subst.
  constructor; [| apply IH; exact ND']. intros K. apply NI. apply in_map. exact K.
Qed.

Lemma NoDup_ids_perm : forall (L L' : list block), Permutation L L' -> List.NoDup (map blk_id L) -> List.NoDup (map blk_id L').
Proof. intros L L' PE ND. eapply Permutation_NoDup; [apply Permutation_map; exact PE| exact ND]. Qed.

Lemma NoDup_ids_app_l : forall (L1 L2 : list block), List.NoDup (map blk_id (L1 ++ L2)) -> List.NoDup (map blk_id L1).
Proof. intros L1 L2 ND. rewrite map_app in ND. exact (List.NoDup_app_remove_r _ _ ND). Qed.
Lemma NoDup_ids_app_r : forall (L1 L2 : list block), List.NoDup (map blk_id (L1 ++ L2)) -> List.NoDup (map blk_id L2).
Proof. intros L1 L2 ND. rewrite map_app in ND. exact (List.NoDup_app_remove_l _ _ ND). Qed.

Lemma NoDup_app_disjoint : forall {A : Type} (l1 l2 : list A) (x : A), List.NoDup (l1 ++ l2) -> In x l1 -> In x l2 -> False.
Proof.
  intros A l1 l2 x ND I1 I2. induction l1 as [|y l1 IH]; [destruct I1|]. cbn in ND. inversion ND as [|z l NI ND']; subst.
  destruct I1 as [<-|I1]; [apply NI; apply in_or_app; right; exact I2| exact (IH ND' I1)].
Qed.

(* [comment removed for export] *)
Lemma mine_fresh : forall (mine LB : list block) b,
  List.NoDup (map blk_id (mine ++ LB)) -> In b mine -> ~ In (blk_id b) (map blk_id LB).
Proof.
  intros mine LB b ND IN K. rewrite map_app in ND. eapply (NoDup_app_disjoint _ _ (blk_id b) ND); [apply in_map; exact IN| exact K].
Qed.

Lemma NoDup_hd_ne : forall {A} (a b : A) l, List.NoDup (a :: l) -> In b l -> a <> b.
Proof. intros A a b l ND IN E. subst. inversion ND; subst. contradiction. Qed.

(* [comment removed for export] *)
Lemma perm_of_members : forall (L L' : list block),
  List.NoDup (map blk_id L) -> List.NoDup (map blk_id L') -> (forall b, In b L <-> In b L') -> Permutation L L'.
Proof. intros L L' N1 N2 MEM. apply Permutation.NoDup_Permutation; [apply NoDup_of_ids; exact N1| apply NoDup_of_ids; exact N2| exact MEM]. Qed.

