Definition keeps_at (L L' : list block) (a : Z) : Prop := forall p n, In (p, a, n) L -> In (p, a, n) L'.

Lemma AAllocImpl_reix : forall L L' m a, keeps_at L L' a -> AAllocImpl L m a -> AAllocImpl L' m a.
Proof. intros L L' m a K (p & j & IN & C). exists p, j. split; [apply K; exact IN| exact C]. Qed.
Lemma ARegistry_reix : forall L L' m r o f lk, keeps_at L L' r -> ARegistry L m r o f lk -> ARegistry L' m r o f lk.
Proof. intros L L' m r o f lk K (p & j0 & j7 & IN & C). exists p, j0, j7. split; [apply K; exact IN| exact C]. Qed.
Lemma AConfigSvc_reix : forall L L' m c S, keeps_at L L' c -> AConfigSvc L m c S -> AConfigSvc L' m c S.
Proof. intros L L' m c S K (p & j4 & j7 & IN & C). exists p, j4, j7. split; [apply K; exact IN| exact C]. Qed.
Lemma AStreamSvc_reix : forall L L' m v S i, keeps_at L L' v -> AStreamSvc L m v S i -> AStreamSvc L' m v S i.
Proof. intros L L' m v S i K (p & j7 & IN & C). exists p, j7. split; [apply K; exact IN| exact C]. Qed.
Lemma AScheduler_reix : forall L L' m s S, keeps_at L L' s -> AScheduler L m s S -> AScheduler L' m s S.
Proof.
  intros L L' m s S K (p & j50 & jm & j109 & je & jt & j219 & j7 & IN & C). exists p, j50, jm, j109, je, jt, j219, j7.
  split; [apply K; exact IN| exact C].
Qed.
Lemma fb_ok_reix : forall L L' F, keeps_at L L' (fb_begin F) -> fb_ok L F -> fb_ok L' F.
Proof.
  intros L L' F K OK. destruct OK as [E|(p & IN & R)]; [left; exact E| right]. exists p. split; [apply K; exact IN| exact R].
Qed.
Lemma AFlatBuf_reix : forall L L' m a F ds, keeps_at L L' (fb_begin F) -> AFlatBuf L m a F ds -> AFlatBuf L' m a F ds.
Proof. intros L L' m a F ds K (C & OK & R). split; [exact C|]. split; [eapply fb_ok_reix; eauto| exact R]. Qed.
Lemma AImplBlock_reix : forall L L' m b I,
  keeps_at L L' b -> (0 < im_vcap I -> keeps_at L L' (im_vb I)) -> AImplBlock L m b I -> AImplBlock L' m b I.
Proof.
  intros L L' m b I K KV (p & j7 & IN & RB & CH & OK & EV & PM & VC & LE & ST & AD). exists p, j7.
  split; [apply K; exact IN|]. repeat (split; [assumption|]). split; [| exact AD].
  destruct ST as [X|(q & junk & INq & RBq & CAP & RC)]; [left; exact X| right]. exists q, junk.
  split; [apply (KV CAP); exact INq|]. split; [exact RBq|]. split; [exact CAP| exact RC].
Qed.
Lemma AImplBlockC_reix : forall L L' m b I,
  keeps_at L L' b -> (0 < im_vcap I -> keeps_at L L' (im_vb I)) -> AImplBlockC L m b I -> AImplBlockC L' m b I.
Proof.
  intros L L' m b I K KV (p & j7 & IN & RB & CH & OK & EV & PM & VC & LE & ST & AD). exists p, j7.
  split; [apply K; exact IN|]. repeat (split; [assumption|]). split; [| exact AD].
  destruct ST as [X|(q & junk & INq & RBq & CAP & RC)]; [left; exact X| right]. exists q, junk.
  split; [apply (KV CAP); exact INq|]. split; [exact RBq|]. split; [exact CAP| exact RC].
Qed.
Lemma AStateBlock_reix : forall L L' m b ioc implb S ds,
  keeps_at L L' b -> (st_fb S <> FB_empty -> keeps_at L L' (fb_begin (st_fb S))) ->
  AStateBlock L m b ioc implb S ds -> AStateBlock L' m b ioc implb S ds.
Proof.
  intros L L' m b ioc implb S ds K KF (p & j7 & j16 & j4 & IN & RB & CH & OK & EV & CE & CW & PM & FB & PC & CO & E).
  exists p, j7, j16, j4. split; [apply K; exact IN|]. repeat (split; [assumption|]). split; [| split; [exact PC| split; [exact CO| exact E]]].
  destruct FB as (C & FOK & R). split; [exact C|]. split; [| exact R].
  destruct FOK as [X|(pf & INf & RBf & CAP & O)]; [left; exact X| right]. exists pf.
  assert (NE : st_fb S <> FB_empty). { intros X. rewrite X in CAP. unfold fb_cap, FB_empty in CAP. cbn in CAP. lia. }
  split; [apply (KF NE); exact INf|]. split; [exact RBf|]. split; [exact CAP| exact O].
Qed.

Lemma keeps_at_mono : forall L L' a, (forall b, In b L -> In b L') -> keeps_at L L' a.
Proof. intros L L' a SUB p n IN. apply SUB. exact IN. Qed.

Section W.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

  (* [comment removed for export] *)
  Lemma ablk_same' : forall s LB m b1 b2, as_RHEAP H s LB m -> In b1 LB -> In b2 LB -> blk_addr b1 = blk_addr b2 -> b1 = b2.
  Proof.
    intros s LB m b1 b2 HP I1 I2 E. destruct (bptr_eq_dec (blk_id b1) (blk_id b2)) as [Ei|NE].
    - exact (nodup_blk_eq LB _ _ (ah_nodup H HH _ _ _ HP) I1 I2 Ei).
    - exfalso. pose proof (ah_blocks H HH _ _ _ _ HP I1) as (_ & _ & K1 & _). pose proof (ah_blocks H HH _ _ _ _ HP I2) as (_ & _ & K2 & _).
      destruct (ah_disj H HH _ _ _ _ _ HP I1 I2 NE); lia.
  Qed.
  Lemma in_pin : forall s L m p0 A n p n', as_RHEAP H s L m -> In (p0, A, n) L -> In (p, A, n') L -> p = p0 /\ n' = n.
  Proof.
    intros s L m p0 A n p n' HP IN0 IN. pose proof (ablk_same' _ _ _ _ _ HP IN IN0 eq_refl) as E. injection E as E1 E2. split; [exact E1| exact E2].
  Qed.

  (* [comment removed for export] *)
  Lemma reix_addr : forall s L m L' (P : block -> Prop) b0,
    as_RHEAP H s L m -> (forall b, In b L' <-> In b L /\ ~ P b) -> In b0 L -> ~ P b0 -> keeps_at L L' (blk_addr b0).
  Proof.
    intros s L m L' P b0 HP MEM IN0 NP p n IN. apply (proj2 (MEM _)).
    pose proof (ablk_same' _ _ _ _ b0 HP IN IN0 eq_refl) as E. split; [exact IN|]. rewrite E. exact NP.
  Qed.
  (* [comment removed for export] *)
  Lemma reix_sub : forall s L m L' b0,
    as_RHEAP H s L m -> (forall b, In b L' -> In b L) -> In b0 L' -> keeps_at L L' (blk_addr b0).
  Proof.
